@use '@smart/web-components/dist/scss/variables' as *;

$space: var(--spacing-700);

%flex-gap {
  width: 100%;
  gap: var(--col-1);
}

.hidden {
  @include breakpoint('l') {
    display: none;
  }
}

@mixin full-width {
  @include breakpoint('l') {
    width: 100%;
  }
}

.flexibleTableWrapper {
  padding: $space var(--content-margin-reduced);

  &.removeTopSpacing {
    padding-top: 0;
  }

  .segmentSelector {
    & div {
      width: fit-content;
    }
  }

  .mainContent {
    flex-direction: column;
    margin-top: var(--spacing-400);
    position: relative;

    .textWrapper {
      flex-direction: column;

      @include full-width;

      @include breakpoint('l') {
        width: var(--col-12);
      }

      & > div {
        width: fit-content;
      }

      .segmentButtonPC {
        width: 100%;
        display: none;

        @include breakpoint('l') {
          display: flex;
        }
      }
    }

    .segmentButtonPhone {
      display: flex;

      @include breakpoint('l') {
        display: none;
      }
    }

    @include breakpoint('l') {
      flex-direction: row;
    }

    @include breakpoint('m') {
      margin-top: $space;
    }

    .subline {
      font-size: 16px !important;
      word-break: break-all;
      margin-bottom: var(--spacing-0);
      width: 100%;

      @include breakpoint('s') {
        margin-bottom: var(--spacing-400);
      }
    }
  }

  .flex-gap {
    @extend %flex-gap;
  }

  &Shink {
    padding-top: $space;
    flex-direction: column;
    display: none;

    @include breakpoint('l') {
      display: flex;
    }

    .tableWrapper {
      margin-top: 0;
    }

    .horizontalGap {
      @extend %flex-gap;

      div {
        // has image and button, button group need self-end to subline
        &:has(.segButtonEnd) {
          display: none;
          align-self: end;
          margin-bottom: var(--spacing-400);

          @include breakpoint('l') {
            display: flex;
          }
        }
      }
    }

    .bottomLayout {
      align-items: start;

      & > * {
        width: 50%;
      }
    }

    .subline {
      margin-bottom: var(--spacing-400);
    }
  }
}

.onlyTextTable {
  .headline {
    margin-bottom: var(--spacing-400);
  }
}

.darkMode {
  color: var(--color-white);
  background-color: var(--color-black);
}

